/** Names in session_index are authored/generated by the desktop separately
 * from SQLite's first-message preview. Read-only import must keep both roles. */
export function isPlaceholderTaskTitle(value: unknown): boolean {
  if (typeof value !== "string") return true;
  return /^(?:New Sofia task|Sofia task|New session)?$/i.test(value.trim());
}

export function parseCodexSessionTitles(jsonl: string): Map<string, string> {
  const titles = new Map<string, string>();
  for (const line of jsonl.split(/\r?\n/)) {
    try {
      const record: unknown = JSON.parse(line);
      if (typeof record !== "object" || record === null) continue;
      const id = Reflect.get(record, "id");
      const name = Reflect.get(record, "thread_name");
      if (typeof id === "string" && id.trim() && typeof name === "string" && !isPlaceholderTaskTitle(name)) {
        titles.set(id, name.trim());
      }
    } catch { /* An incomplete final JSONL record must not hide other names. */ }
  }
  return titles;
}

export function selectCodexThreadName(thread: { name?: unknown; title?: unknown }): string {
  for (const value of [thread.name, thread.title]) {
    if (typeof value === "string" && !isPlaceholderTaskTitle(value)) return value.trim();
  }
  return "";
}

/** Longest title we keep before cutting on a word boundary. */
export const THREAD_TITLE_MAX_LENGTH = 72;

/**
 * The engine titles a task from its first user message, verbatim — so a pasted
 * diff, a `//` comment banner, a stack trace or a wall of markdown all arrive as
 * the title, and the session header ends up rendering a fragment of code. A
 * title has to read as a title: keep the first line that carries words, drop the
 * markdown and comment noise around it, collapse whitespace, and cut on a word
 * boundary so it never ends mid-word (or starts on the halves the engine left).
 */
export function threadTitleFromEngineText(text: unknown): string {
  const input = typeof text === "string" ? text : "";
  const requestMarker = /^## My request:\s*$/m.exec(input);
  const raw = requestMarker ? input.slice(requestMarker.index + requestMarker[0].length) : input;
  let inFence = false;
  for (const rawLine of raw.split(/\r?\n/)) {
    if (/^\s*```/.test(rawLine)) {
      inFence = !inFence;
      continue;
    }
    if (inFence) continue;
    const line = rawLine
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
      .replace(/https?:\/\/\S+/g, " ")
      .replace(/^\s*>+\s*/, "")                    // blockquote
      .replace(/^\s*(?:[-*+]|\d+[.)])\s+/, "")     // list marker
      .replace(/^\s*#{1,6}\s*/, "")                // heading
      .replace(/^\s*\/\/+\s*/, "")                 // line comment
      .replace(/^\s*\/\*+\s*/, "")                // block comment opener
      .replace(/\*\/\s*$/, "")                    // …and its closer
      // A pasted `//` banner ends the sentence the user actually wrote.
      .replace(/(?<!:)\/\/(?=\s|$).*$/, " ")
      .replace(/`{1,3}/g, "")                       // code span
      .replace(/\*{1,3}(?=\S)|(?<=\S)\*{1,3}/g, "")  // emphasis markers
      .replace(/^(?:\.{2,}|…)\s*\S*\s+/, "")       // the half-word a truncation left
      .replace(/\s+/g, " ")
      .trim();
    if (!line) continue;
    if (!/[\p{L}\p{N}]/u.test(line)) continue;
    if (line.length <= THREAD_TITLE_MAX_LENGTH) return line;
    const cut = line.slice(0, THREAD_TITLE_MAX_LENGTH);
    const boundary = cut.lastIndexOf(" ");
    const head = boundary > 24 ? cut.slice(0, boundary) : cut;
    return `${head.replace(/[\s,;:.!?/-]+$/, "")}…`;
  }
  return "";
}

export function threadDisplayTitle(thread: { name?: unknown; title?: unknown; preview?: unknown }): string {
  const name = selectCodexThreadName(thread);
  if (name) return name;
  return threadTitleFromEngineText(thread.preview);
}

